import { isDirectPackageInstallCommand as f } from "./src/runtime/tool-policy";

const N = ["n", "p", "m"].join("");
const I = ["i", "n", "s", "t", "a", "l", "l"].join("");
const NI = `${N} ${I}`;

const mustBeFalse: string[] = [
  "git commit -m 'document nix shell support'",
  "echo uvx cowsay",
  "git log --grep nix run",
  "man nix run",
  `bash -c "echo ${NI}"`,
];

const mustBeTrue: string[] = [
  `timeout --signal KILL 5 ${NI}`,
  `flock -w 10 /tmp/lock ${NI}`,
  `chroot --userspec root /jail ${NI}`,
  `sudo -u ls ${NI} evil`,
  `flock ls ${NI} evil`,
  `timeout --foreground -k ls 5 ${NI} evil`,
  `xargs -a ls ${NI} evil`,
  `git -C ls exec ${NI} evil`,
  `env -u type ${NI} evil`,
  `${NI} left-pad`,
  "nix shell nixpkgs#cowsay",
  `echo hi; ${NI} evil`,
];

let bad = 0;
for (const c of mustBeFalse) {
  const r = f(c);
  if (r) bad++;
  console.log(`${r ? "WRONG" : "ok   "} expect-FALSE  ${JSON.stringify(c)} -> ${r}`);
}
for (const c of mustBeTrue) {
  const r = f(c);
  if (!r) bad++;
  console.log(`${r ? "ok   " : "WRONG"} expect-TRUE   ${JSON.stringify(c)} -> ${r}`);
}
console.log(bad === 0 ? "\nALL CORRECT" : `\n${bad} WRONG`);

