// Dropping the tail is only sound while the tail is INERT TEXT. A command
// substitution runs even as an argument — `echo `npm install x`` installs —
// so the moment the tail carries substitution syntax this refuses to narrow
// at all and matches the whole command. Fail toward flagging, per the
// asymmetry documented on {@link isDirectPackageInstallCommand}: it is a
// guard, not another parsing layer, so nothing here tries to find the end
// of the substitution.
const tailRuns =
  dataAt !== -1 && /[`]|\$\(/.test(words.slice(dataAt).join(" "));
const head = (
  dataAt === -1 || tailRuns ? words : words.slice(0, dataAt)
).join(" ");
if (head && matches(head)) {
  return true;
}

