test("a tail that can RUN something is never dropped (#2279)", () => {
  // Narrowing assumes the dropped tail is inert TEXT. Command substitution
  // executes even as an argument to echo, so a manager inside one must still
  // flag — this is the one direction the matcher may not fail in.
  const bt = String.fromCharCode(96);
  for (const cmd of [
    `echo ${bt}npm install evil${bt}`,
    "echo $(npm install evil)",
    "man $(nix run x)",
    "git log --grep $(uvx cowsay)",
    `printf %s ${bt}pip install evil${bt}`,
  ]) {
    expect(isDirectPackageInstallCommand(cmd)).toBe(true);
  }
  // Plain inert data still narrows, so the guard has not swallowed the fix.
  expect(isDirectPackageInstallCommand("echo uvx cowsay")).toBe(false);
  expect(isDirectPackageInstallCommand("man nix run")).toBe(false);
});

