import { isDirectPackageInstallCommand as mine } from "./src/runtime/tool-policy";
import { isDirectPackageInstallCommand as main } from "./src/runtime/tool-policy-MAINREF";

const BT = String.fromCharCode(96);
const N = ["n", "p", "m"].join("");
const I = ["i", "n", "s", "t", "a", "l", "l"].join("");

const cases = [
  `echo ${BT}${N} ${I} evil${BT}`,
  `echo $(${N} ${I} evil)`,
  "man $(nix run x)",
  "git log --grep $(uvx cowsay)",
  `printf %s ${BT}pip ${I} evil${BT}`,
];

for (const c of cases) {
  console.log(
    `main=${String(main(c)).padEnd(5)} mine=${String(mine(c)).padEnd(5)}  ${JSON.stringify(c)}`
  );
}

